#include "gba/genres/ArenaSurvivalModule.h"
#include "gba/genres/GenreUtil.h"
#include <algorithm>
#include <cmath>
#include <sstream>

namespace gba { using namespace genreutil;
std::string ArenaSurvivalModule::genre()const{return "arena_survival";}
std::vector<ParameterSpec>ArenaSurvivalModule::balanceParameters(const GameDefinition&g)const{std::vector<ParameterSpec>p;for(const auto&w:arrayObjects(g.raw,"weapons")){auto id=str(w,"id");p.push_back(spec("weapon."+id+".powerMul",1,.4,2.6,.2,false,"weapon"));p.push_back(spec("weapon."+id+".cooldownMul",1,.55,1.7,.15,false,"weapon"));p.push_back(spec("weapon."+id+".areaMul",1,.5,2.3,.18,false,"role"));p.push_back(spec("weapon."+id+".upgradeMul",1,.5,2.4,.18,false,"upgrade"));}for(const auto&e:arrayObjects(g.raw,"enemies")){auto id=str(e,"id");p.push_back(spec("enemy."+id+".hpMul",1,.5,2.5,.18));p.push_back(spec("enemy."+id+".damageMul",1,.5,2.2,.18));p.push_back(spec("enemy."+id+".xpMul",1,.6,1.8,.15));}p.push_back(spec("spawn.early",1,.65,1.5,.15));p.push_back(spec("spawn.mid",1,.55,1.8,.17));p.push_back(spec("spawn.late",1,.5,2.2,.2));p.push_back(spec("xp.global",1,.65,1.6,.14));return p;}
std::vector<ParameterSpec>ArenaSurvivalModule::strategyParameters(const GameDefinition&g)const{std::vector<ParameterSpec>p;for(const auto&w:arrayObjects(g.raw,"weapons")){auto id=str(w,"id");p.push_back(spec("pref."+id,1,.02,4,.22));}p.push_back(spec("mobility",1,.2,2.2,.2));p.push_back(spec("greed",.5,0,1.5,.18));p.push_back(spec("upgradeFocus",.8,.1,2,.18));return p;}
SimulationResult ArenaSurvivalModule::simulate(const GameDefinition&g,const Genome&b,const Genome&s,std::uint64_t seed,int maxP)const{std::mt19937_64 rng(seed);SimulationResult r;r.strategyId=s.id;r.balanceId=b.id;r.seed=seed;auto weapons=arrayObjects(g.raw,"weapons"),enemies=arrayObjects(g.raw,"enemies");auto rules=g.raw["rules"];double hp=attr(rules,"playerHp",100),startHp=hp,xp=0,level=1;std::map<std::string,double>levels;double income=0,early=startHp;for(int t=1;t<=maxP;++t){double phase=t<=20?gene(b,"spawn.early"):t<=70?gene(b,"spawn.mid"):gene(b,"spawn.late");double count=(attr(rules,"spawnBase",8)+t*attr(rules,"spawnGrowth",.45))*phase*(.9+.2*rand01(rng));double ehp=0,incoming=0,xpPool=0;double crowd=clamp01((count-15)/40.0),boss=(t%static_cast<int>(attr(rules,"bossInterval",25))==0)?1.0:0.0,fast=0;for(const auto&e:enemies){auto id=str(e,"id"),role=str(e,"role","normal");double sh=attr(e,"share",1);double n=count*sh/std::max(1.0,(double)enemies.size());double h=attr(e,"hp",10)*gene(b,"enemy."+id+".hpMul")*std::pow(1.025,t);double dmg=attr(e,"damage",2)*gene(b,"enemy."+id+".damageMul");ehp+=n*h;incoming+=n*dmg*.03;xpPool+=n*attr(e,"xp",1)*gene(b,"enemy."+id+".xpMul")*gene(b,"xp.global");if(role=="fast")fast+=sh;if(role=="boss")boss=1;}
 while(xp>=level*attr(rules,"xpPerLevel",18)){xp-=level*attr(rules,"xpPerLevel",18);level++;const Json*best=nullptr;double bestU=-1;for(const auto&w:weapons){auto id=str(w,"id"),role=str(w,"role","allround");double u=s.get("pref."+id,1)*roleMatch(role,0,crowd,boss,0,fast)*(1+.12*levels[id])* (.9+.2*rand01(rng));if(u>bestU){bestU=u;best=&w;}}if(best){auto id=str(*best,"id");levels[id]++;r.usage[id]++;}}
 double dps=0,control=0;for(const auto&w:weapons){auto id=str(w,"id"),role=str(w,"role","allround");double lv=levels[id];if(lv<=0&&level>1&&s.get("pref."+id,1)>1.5){lv=.5;}if(lv<=0)continue;double p=attr(w,"power",8)*gene(b,"weapon."+id+".powerMul")*(1+lv*.32*gene(b,"weapon."+id+".upgradeMul"));double cd=std::max(.25,attr(w,"cooldown",1)*gene(b,"weapon."+id+".cooldownMul"));double area=std::pow(gene(b,"weapon."+id+".areaMul"),.7);double rm=roleMatch(role,0,crowd,boss,0,fast);double c=p/cd*area*rm*(1+std::min(2.0,count/25.0));dps+=c;r.contribution[id]+=c;if(role=="control")control+=.12*lv;}
 double killed=clamp01(dps*5/std::max(1.0,ehp));double mobility=s.get("mobility",1);double damageTaken=incoming*(1-killed)*std::max(.18,1-.28*mobility-.08*control);hp-=damageTaken;xp+=xpPool*killed;income+=xpPool*killed;r.metrics["level"]=level;r.metrics["enemyCount"]+=count;if(t==5)early=std::max(0.0,hp);r.progress=t;if(hp<=0){r.success=false;break;}}
r.success=r.progress>=maxP;r.earlySafety=clamp01(early/startHp);r.resourceIncome=std::max(1.0,income);r.resourceResidual=xp;r.score=r.progress*30+r.earlySafety*500+r.success*1000;return r;}
EvaluationSummary ArenaSurvivalModule::evaluateBalance(const GameDefinition&g,const Genome&b,const std::vector<SimulationResult>&runs)const{auto e=IGameModule::evaluateBalance(g,b,runs);double target=g.raw["targets"]["targetProgress"].asNumber(100);e.fitness+=e.earlySafety*1800-std::max(0.0,e.topPairShare-.80)*5000;if(e.avgProgress<target*.75)e.fitness-=(target*.75-e.avgProgress)*45;if(e.avgProgress>target*1.08)e.fitness-=(e.avgProgress-target*1.08)*20;std::ostringstream o;o<<"Arena target="<<e.fitness<<" progress="<<e.avgProgress<<" duo="<<e.topPairShare;e.explanation=o.str();return e;}
std::vector<Genome>ArenaSurvivalModule::targetedBalanceExperiments(const GameDefinition&g,const Genome&base,const EvaluationSummary&c,std::uint64_t&nid,int gen,std::mt19937_64&,double strength)const{std::vector<Genome>v;std::string hi,lo;double a=-1,z=1e99;for(const auto&w:arrayObjects(g.raw,"weapons")){auto id=str(w,"id");double x=c.meanContribution.count(id)?c.meanContribution.at(id):0,u=c.meanUsage.count(id)?c.meanUsage.at(id):0;if(x>a){a=x;hi=id;}if(u<z){z=u;lo=id;}}if(!hi.empty()&&!lo.empty()&&hi!=lo){Genome n=base;n.id=nid++;n.generation=gen;n.note="anti-meta:"+hi+"->"+lo;n.genes["weapon."+hi+".powerMul"]*=1-strength*.35;n.genes["weapon."+lo+".powerMul"]*=1+strength*.35;n.genes["weapon."+lo+".areaMul"]*=1+strength*.2;v.push_back(n);}return v;}
}
